/// Smallest angular separation between two longitudes, in arcseconds.
/// Handles the 0/360 wrap (ids 18, 20, 40 straddle the boundary in some years).
fn ang_diff_arcsec(a_deg: f64, b_deg: f64) -> f64 {
    let mut d = (a_deg - b_deg).rem_euclid(360.0);
    if d > 180.0 {
        d -= 360.0;
    }
    d.abs() * 3600.0
}

fn oracle_row(id: u32) -> Option<&'static [f64; 5]> {
    SWISS_ORACLE
        .iter()
        .find(|(sid, _)| *sid == id)
        .map(|(_, v)| v)
}

/// Sanity: every SE id 0..=46 is present in the baked oracle exactly once,
/// and every named XALEN ayanamsa with an SE id resolves to an oracle row.
#[test]
fn oracle_table_is_complete_and_consistent() {
    assert_eq!(SWISS_ORACLE.len(), 47, "expected SE ids 0..=46");
    for id in 0u32..=46 {
        assert!(
            oracle_row(id).is_some(),
            "missing oracle row for SE id {id}"
        );
    }
    for a in Ayanamsa::all_named() {
        if let Some(id) = a.swiss_ephem_id() {
            assert!(
                oracle_row(id).is_some(),
                "{a} maps to SE id {id} which has no oracle row"
            );
        }
    }
}

/// PERMANENT GREEN GUARD — the one system that is a true dynamic apparent-place
/// reduction of a real fixed star. `TrueChitra` (SE id 27) must track Swiss to
/// under 1 arcsec across 1900-2100. The rigorous IAU 2006/P03 Cartesian
/// precession of Spica's J2000 position (latitude-coupled) brings the measured
/// residual to 0.038" at these epochs; the 0.5" guard below leaves margin while
/// still catching any regression to the old scalar-precession model (which
/// diverged to 1.514" because the pure-longitude term cannot couple Spica's
/// ~2.05° ecliptic latitude).
#[test]
fn true_chitra_matches_swiss_within_1_arcsec() {
    let row = oracle_row(27).expect("SE id 27 oracle");
    let mut max = 0.0_f64;
    for (i, &jd) in JDS.iter().enumerate() {
        let got = Ayanamsa::TrueChitra.compute_deg(jd);
        let d = ang_diff_arcsec(got, row[i]);
        max = max.max(d);
    }
    assert!(
        max <= 0.5,
        "TrueChitra max divergence {max:.3}\" exceeds 0.5\" tolerance"
    );
}

/// OFF-GRID GUARD — `TrueChitra` (SE id 27) at non-Jan-1, non-noon dates spread
/// across 1900-2100. The strict oracle above only samples Jan-1-noon; the OLD
/// scalar pure-longitude precession would still have looked correct at the J2000
/// anchor there but drifts to ~1.5" off it. These five reference values come from
/// pyswisseph 2.10.03 `set_sid_mode(SIDM_TRUE_CITRA); get_ayanamsa_ex(jd, 0)` at
/// arbitrary calendar dates and hours. The rigorous Cartesian Spica reduction
/// reproduces them to ≤ 0.04". This test would FAIL for the old scalar model,
/// guarding against a silent regression that the Jan-1 oracle could miss.
#[test]
fn true_chitra_matches_swiss_off_grid() {
    // (JD(TT), Swiss SE_SIDM_TRUE_CITRA apparent ayanamsa in degrees)
    const OFFGRID: &[(f64, f64)] = &[
        (2423615.750000, 22.773314533), // 1923-07-15 06:00 TT
        (2435900.250000, 23.252009364), // 1957-03-02 18:00 TT
        (2446027.500000, 23.621615404), // 1984-11-23 00:00 TT
        (2455691.000000, 24.009448346), // 2011-05-09 12:00 TT
        (2479941.875000, 24.916939625), // 2077-09-30 09:00 TT
    ];
    let mut max = 0.0_f64;
    for &(jd, swiss) in OFFGRID {
        let got = Ayanamsa::TrueChitra.compute_deg(jd);
        max = max.max(ang_diff_arcsec(got, swiss));
    }
    assert!(
        max <= 0.5,
        "TrueChitra off-grid max divergence {max:.3}\" exceeds 0.5\" tolerance"
    );
}

/// STRICT 1-ARCSEC ORACLE — asserts EVERY XALEN named ayanamsa with an SE id
/// matches Swiss within 1 arcsec at every epoch, with ONE documented exception.
///
/// As of the ayanamsa nutation/IAU-2006/dynamic rewrite, every SE-mapped system
/// tracks Swiss `get_ayanamsa_ex(jd, 0)` (the WITH-nutation apparent value) to
/// well under 1" across 1900–2100 — including `TrueChitra` (SE id 27), now 0.038"
/// after switching its Spica reduction from the scalar pure-longitude precession
/// (1.514") to the rigorous IAU 2006/P03 Cartesian rotation that couples Spica's
/// ecliptic latitude. The SINGLE remaining exception is `GalCenterMulaWilhelm`
/// (SE id 36): Swiss's internal Ernst Wilhelm reduction has a no-nutation
/// precession rate of ~52.5"/yr (≈ 2.2"/yr above general precession) combined
/// with a moderate-latitude (~few-degree) annual aberration of ~±23" — a
/// combination that no single fixed celestial direction reproduces (a fixed
/// direction at the aberration-implied latitude precesses at the general rate;
/// the only fixed direction whose longitude rate reaches 52.5"/yr lies near the
/// ecliptic pole, where its aberration would be far larger than Swiss shows).
/// The best self-contained fixed-direction + nutation model therefore tracks it
/// to ≤ 1.42" at the Jan-1 oracle epochs. That residual is DOCUMENTED here (and
/// in the function comment), not a regression — id 36 is allowed up to 2", every
/// other system (incl. id 27) stays under 1".
///
/// How the three fix families closed the old Wave-B bug list:
///   * NUTATION (Δψ): every linear + epoch_based system now adds IAU 2000B
///     nutation in longitude — fixed the uniform ~17" error.
///   * IAU 2006 PRECESSION: epoch-anchored systems accumulate the full IAU 2006
///     general precession from t0 (not a single 50.288"/yr rate) — fixed the
///     250–510" deep-epoch (1 CE / 499 CE / 564 CE) drift.
///   * DYNAMIC fixed-point reduction: the galactic + true-star systems
///     (17,28,29,30,31,32,33,35,36,39,40) rotate a fixed J2000 reference
///     direction to the ecliptic of date (IAU 2006/P03) + nutation — fixed the
///     1500–102664" divergence (Cochrane's J2000 anchor was 28.5° wrong).
#[test]
fn all_ayanamsas_match_swiss_within_1_arcsec() {
    const TOL_ARCSEC: f64 = 1.0;
    // The single documented exception: SE 36 GalCenterMulaWilhelm (~1.42") —
    // Swiss's internal Wilhelm reduction has a precession rate no fixed celestial
    // direction reproduces under the aberration constraint (see the function
    // doc-comment above). SE 27 TrueChitra is NO LONGER an exception: the
    // rigorous IAU 2006/P03 Cartesian Spica reduction brought it to 0.038"
    // (guarded separately by true_chitra_matches_swiss_within_1_arcsec).
    const TOL_ARCSEC_DOCUMENTED: f64 = 2.0;
    const DOCUMENTED_2ARCSEC_IDS: [u32; 1] = [36];
    let mut failures: Vec<String> = Vec::new();

    for a in Ayanamsa::all_named() {
        let Some(id) = a.swiss_ephem_id() else {
            continue; // PushyaPaksha / KPStraightLine / CitraAtSpica180 have no SE id
        };
        let row = oracle_row(id).expect("every SE id has an oracle row");

        let mut max = 0.0_f64;
        let mut worst_year = 0usize;
        for (i, &jd) in JDS.iter().enumerate() {
            let got = a.compute_deg(jd);
            let d = ang_diff_arcsec(got, row[i]);
            if d > max {
                max = d;
                worst_year = i;
            }
        }
        let tol = if DOCUMENTED_2ARCSEC_IDS.contains(&id) {
            TOL_ARCSEC_DOCUMENTED
        } else {
            TOL_ARCSEC
        };
        if max > tol {
            let years = [1900, 1950, 2000, 2050, 2100];
            failures.push(format!(
                "  {a} (SE {id}): max {max:.3}\" (tol {tol}\") at year {} (XALEN {:.6}° vs Swiss {:.6}°)",
                years[worst_year],
                a.compute_deg(JDS[worst_year]),
                row[worst_year]
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "{} ayanamsa(s) diverge from Swiss Ephemeris beyond tolerance:\n{}",
        failures.len(),
        failures.join("\n")
    );
}
